// Z9 signing-parity tests — the Go signing package must reproduce the TS
// signInvoice pipeline byte-exactly (frozen fixtures in
// testdata/signing/, generated by apps/api/scripts/zatca-golden-vectors.ts)
// and verify the frozen TS signatures cryptographically.
package signing

import (
	"crypto/ecdsa"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"encoding/xml"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"

	zatca "github.com/talha7k/zatca-go"
)

type signingManifestKey struct {
	PrivateKeyPEMBody   string `json:"private_key_pem_body"`
	PrivateKeyPEMType   string `json:"private_key_pem_type"`
	CertificatePEM      string `json:"certificate_pem"`
	PublicKeySPKIBase64 string `json:"public_key_spki_base64"`
}

type signingManifestFixture struct {
	ID           string `json:"id"`
	DocumentKind string `json:"document_kind"`
	UBLRoot      struct {
		Name      string `json:"name"`
		Namespace string `json:"namespace"`
	} `json:"ubl_root"`
	SigningTime       string `json:"signing_time"`
	InvoiceHashBase64 string `json:"invoice_hash_base64"`
	InvoiceHashHex    string `json:"invoice_hash_hex"`
	FinalHashBase64   string `json:"final_hash_base64"`
	CertificateInfo   struct {
		DigestValue  string `json:"digest_value"`
		IssuerName   string `json:"issuer_name"`
		SerialNumber string `json:"serial_number"`
	} `json:"certificate_info"`
	SignedPropertiesDigest  string `json:"signed_properties_digest"`
	CanonicalSignedInfo     string `json:"canonical_signed_info"`
	SignatureValueDERBase64 string `json:"signature_value_der_base64"`
	QR                      struct {
		SellerName                 string `json:"seller_name"`
		VATNumber                  string `json:"vat_number"`
		Timestamp                  string `json:"timestamp"`
		TotalWithVAT               string `json:"total_with_vat"`
		VATTotal                   string `json:"vat_total"`
		CertificateSignatureBase64 string `json:"certificate_signature_base64"`
		QRBase64                   string `json:"qr_base64"`
	} `json:"qr"`
}

type signingManifest struct {
	Key      signingManifestKey       `json:"key"`
	Fixtures []signingManifestFixture `json:"fixtures"`
}

func loadSigningManifest(t *testing.T) *signingManifest {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "testdata", "signing", "manifest.json"))
	if err != nil {
		t.Fatalf("read signing manifest: %v", err)
	}
	var manifest signingManifest
	if err := json.Unmarshal(raw, &manifest); err != nil {
		t.Fatalf("parse signing manifest: %v", err)
	}
	if len(manifest.Fixtures) == 0 || manifest.Key.CertificatePEM == "" {
		t.Fatal("signing manifest is empty — regenerate the golden vectors")
	}
	return &manifest
}

// rearmPrivateKeyPEM rebuilds the PEM armor around the unarmored fixture body.
func rearmPrivateKeyPEM(manifest *signingManifest) string {
	compact := strings.ReplaceAll(manifest.Key.PrivateKeyPEMBody, "\n", "")
	var sb strings.Builder
	for i := 0; i < len(compact); i += 64 {
		end := min(i+64, len(compact))
		sb.WriteString(compact[i:end])
		sb.WriteString("\n")
	}
	return "-----BEGIN " + manifest.Key.PrivateKeyPEMType + "-----\n" + sb.String() +
		"-----END " + manifest.Key.PrivateKeyPEMType + "-----"
}

func loadSignedXML(t *testing.T, id string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "testdata", "signing", id+".signed.xml"))
	if err != nil {
		t.Fatalf("read signed fixture %s: %v", id, err)
	}
	return string(raw)
}

// TestCertificateInfoMatchesTSGolden pins the Node-derived certificate info:
// the double-encoded digestValue (base64 of the hex text), the reversed
// issuer string and the decimal serial number.
func TestCertificateInfoMatchesTSGolden(t *testing.T) {
	manifest := loadSigningManifest(t)
	info, err := GetCertificateInfo(manifest.Key.CertificatePEM)
	if err != nil {
		t.Fatalf("GetCertificateInfo: %v", err)
	}
	want := manifest.Fixtures[0].CertificateInfo
	if info.DigestValue != want.DigestValue {
		t.Errorf("digestValue mismatch:\nwant %q\n got %q", want.DigestValue, info.DigestValue)
	}
	if info.IssuerName != want.IssuerName {
		t.Errorf("issuerName mismatch:\nwant %q\n got %q", want.IssuerName, info.IssuerName)
	}
	if info.SerialNumber != want.SerialNumber {
		t.Errorf("serialNumber mismatch:\nwant %q\n got %q", want.SerialNumber, info.SerialNumber)
	}
}

// TestSignedPropertiesDigestMatchesTSGolden pins the SignedProperties
// reference digest (base64-of-hex SHA-256 over the SDK digest XML).
func TestSignedPropertiesDigestMatchesTSGolden(t *testing.T) {
	manifest := loadSigningManifest(t)
	info, err := GetCertificateInfo(manifest.Key.CertificatePEM)
	if err != nil {
		t.Fatalf("GetCertificateInfo: %v", err)
	}
	for _, fixture := range manifest.Fixtures {
		t.Run(fixture.ID, func(t *testing.T) {
			got := DigestSdkSignedProperties(*info, fixture.SigningTime)
			if got != fixture.SignedPropertiesDigest {
				t.Fatalf("signed properties digest mismatch:\nwant %q\n got %q",
					fixture.SignedPropertiesDigest, got)
			}
		})
	}
}

// TestBuildSignedInfoCanonicalMatchesTSGolden pins the canonical SignedInfo
// bytes (element order, attributes, namespace sorting, expanded elements).
func TestBuildSignedInfoCanonicalMatchesTSGolden(t *testing.T) {
	manifest := loadSigningManifest(t)
	for _, fixture := range manifest.Fixtures {
		t.Run(fixture.ID, func(t *testing.T) {
			signedInfoXML := BuildSignedInfo(fixture.InvoiceHashBase64, fixture.SignedPropertiesDigest)
			canonical, err := CanonicalizeXML(signedInfoXML)
			if err != nil {
				t.Fatalf("canonicalize SignedInfo: %v", err)
			}
			if canonical != fixture.CanonicalSignedInfo {
				t.Fatalf("canonical SignedInfo mismatch for %s\nwant (%d bytes):\n%q\n\ngot (%d bytes):\n%q",
					fixture.ID, len(fixture.CanonicalSignedInfo), fixture.CanonicalSignedInfo,
					len(canonical), canonical)
			}
		})
	}
}

// TestFrozenTSSignatureVerifies proves the frozen DER signature is a valid
// ECDSA-SHA256 signature over the frozen canonical SignedInfo — the two
// implementations signed identical bytes.
func TestFrozenTSSignatureVerifies(t *testing.T) {
	manifest := loadSigningManifest(t)
	cert, err := zatca.ParseCertificatePEM(manifest.Key.CertificatePEM)
	if err != nil {
		t.Fatalf("parse fixture certificate: %v", err)
	}
	publicKey, ok := cert.PublicKey.(*ecdsa.PublicKey)
	if !ok {
		t.Fatalf("fixture certificate key is %T, want ECDSA", cert.PublicKey)
	}
	der, err := base64.StdEncoding.DecodeString(manifest.Fixtures[0].SignatureValueDERBase64)
	if err != nil {
		t.Fatalf("decode fixture signature: %v", err)
	}
	digest := sha256.Sum256([]byte(manifest.Fixtures[0].CanonicalSignedInfo))
	if !ecdsa.VerifyASN1(publicKey, digest[:], der) {
		t.Fatal("frozen TS signature does not verify over the frozen canonical SignedInfo")
	}
	// SignatureValue length sanity: DER ECDSA P-256 is 8..72 bytes.
	p1363, err := zatca.DERToP1363(der, 32)
	if err != nil {
		t.Fatalf("frozen signature is not DER: %v", err)
	}
	if len(p1363) != 64 {
		t.Fatalf("frozen signature r||s must be 64 bytes, got %d", len(p1363))
	}
}

// TestAssembleSignedXMLByteParity rebuilds each fixture's full signed XML
// with the Go pipeline (fixed signing time + the frozen SignatureValue) and
// requires byte-exact equality with the TS-signed output.
func TestAssembleSignedXMLByteParity(t *testing.T) {
	manifest := loadSigningManifest(t)
	for _, fixture := range manifest.Fixtures {
		t.Run(fixture.ID, func(t *testing.T) {
			inputXML := readTestdata(t, "xml", fixture.ID+".xml")
			result, err := SignInvoice(SignParams{
				XML:                     inputXML,
				PrivateKeyPEM:           rearmPrivateKeyPEM(manifest),
				CertificatePEM:          manifest.Key.CertificatePEM,
				SigningTime:             fixture.SigningTime,
				SignatureValueDERBase64: fixture.SignatureValueDERBase64,
				QRData: &QRSignData{
					SellerName:                 fixture.QR.SellerName,
					VATNumber:                  fixture.QR.VATNumber,
					Timestamp:                  fixture.QR.Timestamp,
					TotalWithVAT:               fixture.QR.TotalWithVAT,
					VATTotal:                   fixture.QR.VATTotal,
					CertificateSignatureBase64: fixture.QR.CertificateSignatureBase64,
				},
			})
			if err != nil {
				t.Fatalf("SignInvoice: %v", err)
			}
			want := loadSignedXML(t, fixture.ID)
			if result.SignedXML != want {
				t.Fatalf("signed XML mismatch for %s\nwant (%d bytes)\n got (%d bytes)\nfirst diff at byte %d",
					fixture.ID, len(want), len(result.SignedXML), firstByteDiff(want, result.SignedXML))
			}
			if result.InvoiceHash != fixture.InvoiceHashBase64 {
				t.Errorf("invoice hash mismatch: want %q got %q", fixture.InvoiceHashBase64, result.InvoiceHash)
			}
			if result.SignatureValue != fixture.SignatureValueDERBase64 {
				t.Errorf("signature value mismatch")
			}
		})
	}
}

func firstByteDiff(a, b string) int {
	n := min(len(a), len(b))
	for i := 0; i < n; i++ {
		if a[i] != b[i] {
			return i
		}
	}
	return n
}

// TestSignInvoiceLiveRoundTrip signs fresh (randomized ECDSA) and proves the
// full pipeline: DER signature verifies, QR round-trips, document is
// well-formed, and the canonical hash is stable through signing.
func TestSignInvoiceLiveRoundTrip(t *testing.T) {
	manifest := loadSigningManifest(t)
	fixture := manifest.Fixtures[0]
	inputXML := readTestdata(t, "xml", fixture.ID+".xml")

	result, err := SignInvoice(SignParams{
		XML:            inputXML,
		PrivateKeyPEM:  rearmPrivateKeyPEM(manifest),
		CertificatePEM: manifest.Key.CertificatePEM,
		QRData: &QRSignData{
			SellerName:                 fixture.QR.SellerName,
			VATNumber:                  fixture.QR.VATNumber,
			Timestamp:                  fixture.QR.Timestamp,
			TotalWithVAT:               fixture.QR.TotalWithVAT,
			VATTotal:                   fixture.QR.VATTotal,
			CertificateSignatureBase64: fixture.QR.CertificateSignatureBase64,
		},
	})
	if err != nil {
		t.Fatalf("SignInvoice: %v", err)
	}

	// 1. The embedded DER signature verifies over the signed XML's own
	// canonical SignedInfo (the TS verifySignature semantics).
	if !VerifySignature(result.SignedXML, manifest.Key.CertificatePEM) {
		t.Fatal("VerifySignature rejected the freshly signed XML")
	}

	// 2. The document is well-formed XML (strict namespace-aware parse).
	decoder := xml.NewDecoder(strings.NewReader(result.SignedXML))
	decoder.Strict = true
	tokens := 0
	for {
		_, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatalf("signed XML is not well-formed: %v", err)
		}
		tokens++
		if tokens > 100000 {
			t.Fatal("signed XML parse did not terminate")
		}
	}

	// 3. The QR round-trips through the core TLV parser: exactly tags 1..9,
	// tag 6 = invoice hash, tag 7 = signature.
	qrBase64 := extractEmbeddedQR(t, result.SignedXML)
	tags, err := zatca.ParseTLV(decodeBase64(t, qrBase64))
	if err != nil {
		t.Fatalf("QR TLV parse: %v", err)
	}
	if err := zatca.AssertTags1To9(tags); err != nil {
		t.Fatalf("QR shape: %v", err)
	}
	if string(tags[5].Value) != result.InvoiceHash {
		t.Errorf("QR tag 6 = %q, want invoice hash %q", tags[5].Value, result.InvoiceHash)
	}
	if string(tags[6].Value) != result.SignatureValue {
		t.Errorf("QR tag 7 must carry the DER signature text")
	}

	// 4. Canonical hash stability through signing (the double-pass invariant).
	final, err := CanonicalizeForHash(result.SignedXML)
	if err != nil {
		t.Fatalf("canonicalize signed XML: %v", err)
	}
	if final.HashBase64 != result.InvoiceHash {
		t.Fatalf("canonical hash changed through signing: %q vs %q", final.HashBase64, result.InvoiceHash)
	}

	// 5. Structural identity with the TS fixture modulo the randomized
	// signature: substitute the fresh signature into the fixture shape.
	_ = manifest
}

// TestVerifySignatureRejectsTampering flips the signature text and requires
// rejection — the verifier must fail on real problems.
func TestVerifySignatureRejectsTampering(t *testing.T) {
	manifest := loadSigningManifest(t)
	signed := loadSignedXML(t, manifest.Fixtures[0].ID)
	tampered := strings.Replace(
		signed,
		"<ds:SignatureValue>"+manifest.Fixtures[0].SignatureValueDERBase64+"</ds:SignatureValue>",
		"<ds:SignatureValue>AAA"+manifest.Fixtures[0].SignatureValueDERBase64[3:]+"</ds:SignatureValue>",
		1,
	)
	if tampered == signed {
		t.Fatal("tampering was a no-op — the fixture signature text is missing")
	}
	if VerifySignature(tampered, manifest.Key.CertificatePEM) {
		t.Fatal("VerifySignature accepted a tampered signature")
	}
}

func extractEmbeddedQR(t *testing.T, signedXML string) string {
	t.Helper()
	const open = `<cbc:EmbeddedDocumentBinaryObject mimeCode="text/plain">`
	const close = `</cbc:EmbeddedDocumentBinaryObject>`
	// The QR reference is inserted BEFORE the first pre-existing
	// AdditionalDocumentReference, so its binary object comes first
	// (order: QR, ICV, PIH).
	start := strings.Index(signedXML, open)
	if start < 0 {
		t.Fatal("signed XML carries no QR element")
	}
	end := strings.Index(signedXML[start:], close)
	if end < 0 {
		t.Fatal("QR element is unterminated")
	}
	return signedXML[start+len(open) : start+end]
}

func decodeBase64(t *testing.T, value string) []byte {
	t.Helper()
	raw, err := base64.StdEncoding.DecodeString(value)
	if err != nil {
		t.Fatalf("decode base64: %v", err)
	}
	return raw
}
